const fs = require('fs');
const { execSync } = require('child_process'); // 🟢 تمت الإضافة لحساب المدة

const items = $input.all();
const publicDir = `C:\\Users\\DEll\\my-video\\public`;
const baseBackgroundsDir = `C:\\Users\\DEll\\my-video\\backgrounds`;

if (!fs.existsSync(publicDir)) fs.mkdirSync(publicDir, { recursive: true });

let mainFolder = `${baseBackgroundsDir}\\main_videos`; 
let satisfyingFolder = `${baseBackgroundsDir}\\satisfying`;
let completedFolder = `${baseBackgroundsDir}\\completed_videos`; 

if (!fs.existsSync(completedFolder)) fs.mkdirSync(completedFolder, { recursive: true });

let mainVideos = fs.existsSync(mainFolder) ? fs.readdirSync(mainFolder).filter(f => f.endsWith('.mp4')) : [];
mainVideos.sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));

let satisfyingVideos = fs.existsSync(satisfyingFolder) ? fs.readdirSync(satisfyingFolder).filter(f => f.endsWith('.mp4')) : [];

if (mainVideos.length === 0 || satisfyingVideos.length === 0) {
    throw new Error("انتهت الفيديوهات! تأكد من وضع فيديوهات جديدة في مجلد main_videos");
}

const finalItems = [];

for (let i = 0; i < items.length; i++) {
    let item = items[i].json;

    let mainVideoName = mainVideos.shift(); 
    if (!mainVideoName) throw new Error("نفدت الفيديوهات الأساسية أثناء المعالجة!");

    let sourceFilePath = `${mainFolder}\\${mainVideoName}`;
    let mainTargetName = `scene_${i}_main.mp4`;
    let targetFilePath = `${publicDir}\\${mainTargetName}`;

    if (fs.existsSync(targetFilePath)) fs.unlinkSync(targetFilePath);
    fs.copyFileSync(sourceFilePath, targetFilePath);

    let completedFilePath = `${completedFolder}\\${mainVideoName}`;
    fs.renameSync(sourceFilePath, completedFilePath);

    let extractedTitle = mainVideoName.replace(/\.[^/.]+$/, ""); 
    item.youtube_title = extractedTitle;
    item.title = extractedTitle;

    // 🟢 السحر هنا: حساب المدة الحقيقية للفيديو الأساسي بدقة عالية 🟢
    let durationInSeconds = 120; // قيمة افتراضية للحماية
    try {
        let cmd = `ffprobe -v error -show_entries format=duration -of default=noprint_wrappers=1:nokey=1 "${targetFilePath}"`;
        let probeResult = execSync(cmd).toString().trim();
        if (probeResult) {
            durationInSeconds = parseFloat(probeResult);
        }
    } catch (e) {
        console.log("ffprobe error: ", e.message);
    }

    // تحويل المدة الحقيقية إلى إطارات (Frames)
    item.durationInFrames = Math.ceil(durationInSeconds * 30); 

    satisfyingVideos.sort(() => Math.random() - 0.5); 
    let urlsRight = [];

    for (let v = 0; v < 24; v++) {
        let satName = satisfyingVideos[v % satisfyingVideos.length]; 
        let satTargetName = `scene_${i}_sat_${v}.mp4`;
        let satTargetPath = `${publicDir}\\${satTargetName}`;
        if (fs.existsSync(satTargetPath)) fs.unlinkSync(satTargetPath);
        fs.copyFileSync(`${satisfyingFolder}\\${satName}`, satTargetPath);
        urlsRight.push(satTargetName);
    }

    item.main_video_url = mainTargetName;
    item.satisfying_urls = urlsRight;
    item.video_type = "dual_video";

    finalItems.push({ json: item });
}

return finalItems;

const currentData = $input.all(); 
const fs = require('fs'); 
const { spawn } = require('child_process');

const projectDir = `C:\\Users\\DEll\\my-video`;
const publicDir = `${projectDir}\\public`;
const runId = Date.now();
const propsPath = `${projectDir}\\props_${runId}.json`;

const scenesArray = currentData.map((item, i) => {
    let scene = item.json;
    // 🟢 السحر هنا: استخدام مدة الفيديو الحقيقية التي حسبها الداونلودر 🟢
    let frames = scene.durationInFrames || 3600; 

    return {
        scene_number: i + 1,
        main_video_url: scene.main_video_url,
        satisfying_urls: scene.satisfying_urls,
        durationInFrames: frames, // تمرير المدة الصحيحة
        title: scene.youtube_title || scene.title || "مقطع ممتع"
    };
});

const finalJson = {
    scenes: scenesArray,
    video_type: "dual_video", 
    title: "Dual_Video"
};

fs.writeFileSync(propsPath, JSON.stringify(finalJson, null, 2));

function runRenderCommand(command, workingDir) {
  return new Promise((resolve, reject) => {
    const process = spawn(command, { shell: true, cwd: workingDir });
    let fullLogs = '';
    process.stdout.on('data', (data) => { fullLogs += data.toString(); });
    process.stderr.on('data', (data) => { fullLogs += data.toString(); });
    process.on('close', (code) => {
      if (code === 0) resolve(fullLogs);
      else reject(new Error(`فشلت الرندرة:\n${fullLogs}`));
    });
  });
}

try {
  let finalTitle = currentData[0].json.youtube_title || currentData[0].json.title || "مقطع_مزدوج";
  const safeTitle = finalTitle.replace(/[<>:"\/\\|?*]+/g, '').trim().substring(0, 80);
  const outputVideoPath = `C:\\Users\\DEll\\.n8n-files\\${safeTitle}.mp4`;

  // 🟢 إضافة --pixel-format yuv420p لضمان الثبات اللوني
  const renderCommand = `npx remotion render src/index.ts MyDualVideo "${outputVideoPath}" --props="${propsPath}" --concurrency=3 --gl=angle --pixel-format=yuv420p --timeout=120000 --log=info`;

  await runRenderCommand(renderCommand, projectDir);

  try {
    if (fs.existsSync(propsPath)) fs.unlinkSync(propsPath);
    const files = fs.readdirSync(publicDir);
    for (const file of files) {
      if (file.startsWith(`scene_`)) fs.unlinkSync(`${publicDir}\\${file}`);
    }
  } catch (e) { }

  const wordsArray = finalTitle.split(/\s+/).filter(word => word.length > 2 && word !== "الجزء" && !/\d/.test(word));
  const hashtagsString = wordsArray.map(word => '#' + word).join(' ');
  const finalDescription = `${finalTitle}\n\nنتمنى لكم مشاهدة ممتعة مع هذا المقطع، لا تنسوا الاشتراك!\n\n${hashtagsString}`;

  return [{ 
      json: { 
          message: `✅ تمت الرندرة بنجاح!`, 
          video_location: outputVideoPath,
          youtube_title: finalTitle,
          youtube_description: finalDescription, 
          youtube_tags: wordsArray               
      } 
  }];
} catch (error) {
  return [{ json: { message: "❌ خطأ أثناء الرندرة!", error_details: error.message } }];
}
